#!/usr/bin/env bash
# Deploy dos handlers das Embaixadoras. COLE ESTE ARQUIVO INTEIRO no EC2 Instance Connect.
set -e
DIR="$(dirname "$(sudo find /var/www -name sync.php 2>/dev/null | head -1)")"
[ -z "$DIR" ] && DIR="/var/www/webhook"
echo "Diretorio dos hooks: $DIR"
ts=$(date +%s)
for f in embaixadora.php embaixadora-optout.php; do
  [ -f "$DIR/$f" ] && sudo cp "$DIR/$f" "$DIR/$f.bak.$ts" && echo "backup $f"
done
echo "" | base64 -d | sudo tee "$DIR/embaixadora.php" >/dev/null
echo "" | base64 -d | sudo tee "$DIR/embaixadora-optout.php" >/dev/null
if [ ! -f "$DIR/embaixadora.config.php" ]; then
  echo "" | base64 -d | sudo tee "$DIR/embaixadora.config.php" >/dev/null
  sudo chmod 600 "$DIR/embaixadora.config.php"
  echo ">> CRIEI embaixadora.config.php -- EDITE: MAUTIC_USER/PASS, YAMPI_TOKEN/SECRET, EMBAIXADORA_WEBHOOK_TOKEN, MAUTIC_OPTOUT_TOKEN."
else
  echo ">> embaixadora.config.php ja existe -- mantido."
fi
sudo touch /var/log/embaixadora.log && sudo chown www-data:www-data /var/log/embaixadora.log 2>/dev/null || true
echo "OK. Teste: curl -s 'https://mautic.aurha.com.br/hook/embaixadora.php?token=fd374b40d3aecf856ae9985bd9165e70' -d '{}'"
